-- Ejecutar en un proyecto NUEVO de Supabase.
create table public.admins (id uuid primary key references auth.users on delete cascade);
create table public.distributors (id uuid primary key references auth.users on delete cascade, ruc text not null unique check(ruc ~ '^[0-9]{11}$'), company text not null, phone text not null, status text not null default 'pending' check(status in ('pending','approved','blocked')));
create table public.settings (id int primary key check(id=1), rate numeric(10,4) not null check(rate>0));
insert into public.settings values (1,3.75);
create table public.products (id bigint generated by default as identity primary key, name text not null, brand text not null, category text not null, price numeric(12,2) not null check(price>=0), currency text not null check(currency in ('USD','PEN')), stock int not null default 0 check(stock>=0), image text not null default '', specs text not null default '', active boolean not null default true, offer boolean not null default false, reference_price numeric(12,2) check(reference_price>price));
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.admins where id=auth.uid()) $$;
create function public.can_read() returns boolean language sql stable security definer set search_path='' as $$ select public.is_admin() or exists(select 1 from public.distributors where id=auth.uid() and status='approved') $$;
create function public.valid_ruc(r text) returns boolean language plpgsql immutable set search_path='' as $$ declare w int[]:=array[5,4,3,2,7,6,5,4,3,2]; s int:=0; i int; begin if r is null or r !~ '^[0-9]{11}$' or left(r,2) not in ('10','15','16','17','20') then return false; end if; for i in 1..10 loop s:=s+substring(r,i,1)::int*w[i]; end loop; return (11-s%11)%10=right(r,1)::int; end $$;
alter table public.distributors add constraint ruc_checksum check(public.valid_ruc(ruc));
alter table public.admins enable row level security;
alter table public.distributors enable row level security;
alter table public.settings enable row level security;
alter table public.products enable row level security;
create policy own_admin on public.admins for select to authenticated using(id=auth.uid());
create policy own_profile on public.distributors for select to authenticated using(id=auth.uid() or public.is_admin());
create policy register_profile on public.distributors for insert to authenticated with check(id=auth.uid() and status='pending');
create policy admin_profiles on public.distributors for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy read_settings on public.settings for select to authenticated using(public.can_read());
create policy edit_settings on public.settings for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy read_products on public.products for select to authenticated using(public.is_admin() or (public.can_read() and active));
create policy edit_products on public.products for all to authenticated using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('b2b-products','b2b-products',false,2097152,array['image/jpeg','image/png','image/webp']);
create policy read_photos on storage.objects for select to authenticated using(bucket_id='b2b-products' and public.can_read());
create policy upload_photos on storage.objects for insert to authenticated with check(bucket_id='b2b-products' and public.is_admin());
create policy delete_photos on storage.objects for delete to authenticated using(bucket_id='b2b-products' and public.is_admin());
